console.log(`Starting literary vocabulary enrichment (Collection size: ${VOCABULARY_LIST.length})...`);
let added = 0;
let skipped = 0;

for (const [word, pos, def, examples, variations] of VOCABULARY_LIST) {
  const cleanWord = word.trim().toLowerCase();
  if (dictionaryManager.hasWord(cleanWord)) {
    skipped++;
    continue;
  }

  const res = dictionaryManager.addWord({
    word: cleanWord,
    meanings: [{
      partOfSpeech: pos,
      definition: def,
      examples: Array.isArray(examples) ? examples : []
    }],
    variations: Array.isArray(variations) ? variations : []
  }, false);

  if (res.added) {
    added++;
  }
}

const stats = dictionaryManager.getStats();
console.log(`Finished enrichment!`);
console.log(`Newly added: ${added}`);
console.log(`Already existed (preserved): ${skipped}`);
console.log(`Total words in dictionary now: ${stats.totalWords}`);
